// swift-tools-version:6.0
// Run ./build.sh first: it builds the Rust library and generates the Swift bindings.
import Foundation
import PackageDescription

let here = URL(fileURLWithPath: #filePath).deletingLastPathComponent().path

let package = Package(
    name: "Diskbloom",
    platforms: [.macOS(.v13)],
    targets: [
        // C header and module map for the Rust library (generated by build.sh into build/ffi)
        .systemLibrary(name: "diskbloom_ffiFFI", path: "build/ffi"),
        // Swift bindings generated by uniffi-bindgen
        .target(
            name: "DiskbloomFFI",
            dependencies: ["diskbloom_ffiFFI"],
            path: "Sources/DiskbloomFFI",
            swiftSettings: [.swiftLanguageMode(.v5)],  // generated code
            linkerSettings: [
                .unsafeFlags(["-L", here + "/build/lib"]),
                .linkedLibrary("diskbloom_ffi"),
                .linkedLibrary("iconv"),  // needed by Rust std on macOS
            ]
        ),
        // Logic without UI: tools, parsing, formatting. Tested by DiskbloomKitTests.
        .target(name: "DiskbloomKit", path: "Sources/DiskbloomKit"),
        // The SwiftUI app
        .executableTarget(
            name: "Diskbloom",
            dependencies: ["DiskbloomFFI", "DiskbloomKit"],
            path: "Sources/Diskbloom"
        ),
        .testTarget(name: "DiskbloomKitTests", dependencies: ["DiskbloomKit"], path: "Tests/DiskbloomKitTests"),
    ]
)
